import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.CWg_RwV0.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"nP.js","text":"Microwave Circuit Analysis Using JavaScript","tagline":"Construct RF networks, analyze S-parameters, and visualize the results.","image":{"src":"/nPortLogo.svg","alt":"nP logo","width":480,"height":480},"actions":[{"theme":"brand","text":"Get started","link":"/agentic-nport"},{"theme":"alt","text":"What's new in 0.49.0","link":"/whats-new-0-49-0"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/JerryWiltz/nP"}]},"features":[{"icon":"🤖","title":"Agentic nPort","details":"Describe your circuit or supply a schematic; your agent writes readable nP code.","link":"/agentic-nport","linkText":"Use Agentic nPort"},{"icon":"🔬","title":"RF network analysis","details":"Build connected networks and calculate S-parameters and stability.","link":"/connecting-nports","linkText":"Analyze RF networks"},{"icon":"📶","title":"Time-domain signals","details":"Generate waveforms, use FFTs, explore modulation and VNA impulse responses.","link":"/digital-signals","linkText":"Explore time-domain signals"},{"icon":"⚡","title":"DC bias analysis","details":"Determine operating points from external bias networks before RF analysis.","link":"/dc-bias-analysis","linkText":"Explore DC bias"},{"icon":"✏️","title":"Schematics and results","details":"Draw circuits and display charts, Smith charts and tables.","link":"/schematics","linkText":"Draw and display results"},{"icon":"📡","title":"Noise and distortion","details":"Calculate noise figure, intermodulation and harmonics.","link":"/noise","linkText":"Analyze noise and distortion"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),s={name:"index.md"};function r(o,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="agentic-nport" tabindex="-1">Agentic nPort <a class="header-anchor" href="#agentic-nport" aria-label="Permalink to &quot;Agentic nPort&quot;">​</a></h2><p><strong>Describe your circuit. Let your agent write the nP code.</strong> Give Codex, Claude or another coding assistant a typed request, existing code, or a scanned or hand-drawn schematic. It supplies the nP syntax and writes explicit, readable code with named components and connections.</p><p>Follow the <a href="./agentic-nport.html">Agentic nPort guide</a> for environment setup, or choose the instructions below and save them as <code>AGENTS.md</code> in your working folder:</p><ul><li><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/html/AGENTS.md" target="_blank" rel="noreferrer">HTML agent</a>: complete, minimal pages using an adjacent <code>nP.js</code>.</li><li><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/obsidian/AGENTS.md" target="_blank" rel="noreferrer">Obsidian agent</a>: Markdown notes with <code>npjs</code> blocks for nPort RF Analysis.</li><li><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/nodejs/AGENTS.md" target="_blank" rel="noreferrer">Node.js agent</a>: scripts using an installed nP package or a supplied module such as <a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/dist/nP.cjs" target="_blank" rel="noreferrer">nP.cjs</a>.</li><li><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/websites/AGENTS.md" target="_blank" rel="noreferrer">Website agent</a>: nP code integrated into an existing site.</li></ul><p>Supply the appropriate nP library and ask your coding assistant to read <code>AGENTS.md</code>. These instructions work outside this repository and need no repository checkout. Locally supplied nP files support offline analysis; the coding assistant has its own connection requirements. The agent writes code by default and runs it when asked. For HTML or website work, the site&#39;s <a href="./nP.js">browser bundle</a> provides <code>nP.js</code>.</p><h2 id="dc-bias-analysis" tabindex="-1">DC bias analysis <a class="header-anchor" href="#dc-bias-analysis" aria-label="Permalink to &quot;DC bias analysis&quot;">​</a></h2><p>The current browser bundle includes <code>nP.V()</code> and network DC solving using the same <code>nodal()</code> or cascade connections as RF analysis. External capacitors open at DC, inductors short, and supported resistive paths remain. Call <code>network.solveDC()</code> when you want an explicit DC result.</p><p>For a supported network containing voltage supplies and NPN/PNP transistors, nP solves the external bias network before building its RF response. Read the returned <code>network.operatingPoint</code> for the solved state. Fixed-Q transistor construction remains available. Diode network DC adapters are not yet supported.</p><p>Start with the <a href="./dc-bias-analysis.html">DC bias analysis guide</a>. See the <a href="https://github.com/JerryWiltz/nP/blob/master/developmentDocs/analysis/dcAnalysis.md" target="_blank" rel="noreferrer">DC analysis details</a> and <a href="./diodes-and-active-components.html">active-device guide</a>. Published npm and Obsidian builds have their own update schedules; use the APIs present in the bundle you supply.</p><h2 id="what-s-new-in-np-0-49-0" tabindex="-1">What&#39;s new in nP 0.49.0 <a class="header-anchor" href="#what-s-new-in-np-0-49-0" aria-label="Permalink to &quot;What&#39;s new in nP 0.49.0&quot;">​</a></h2><p>See <a href="./whats-new-0-49-0.html">What&#39;s new in nP 0.49.0</a> for SVG schematics, time-grid and digital workflows, FFT reconstruction, and VNA examples.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><p>Install the package in a Node.js or browser project:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @jerrywiltz/np</span></span></code></pre></div><p>Import the named API in Node.js or an ESM browser application:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@jerrywiltz/np&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The browser bundle is also available as <code>dist/nP.js</code> and exposes the global <code>nP</code> object. The <a href="https://github.com/JerryWiltz/nP#readme" target="_blank" rel="noreferrer">project README</a> contains a compact API overview and a complete circuit example.</p><h2 id="basic-workflow" tabindex="-1">Basic workflow <a class="header-anchor" href="#basic-workflow" aria-label="Permalink to &quot;Basic workflow&quot;">​</a></h2><ol><li>Set <code>nP.global.fList</code>.</li><li>Create components as n-port objects.</li><li>Connect them with <code>nP.nodal()</code> or <code>nP.cascade()</code>.</li><li>Extract data with <code>.out(...)</code>.</li><li>Draw the network with <code>nP.schematic(network)</code>.</li><li>Display the result with <code>nP.lineChart()</code>, <code>nP.lineTable()</code>, or <code>nP.smithChart()</code>.</li></ol><p>The <a href="./schematics.html">Schematics guide</a> explains how the network&#39;s connections become a drawing, how to use its controls, and how to guide the layout of larger circuits.</p><p>Start with the <a href="./introduction.html">Introduction</a>, then follow the <a href="./tutorial.html">Tutorial</a> for RF and digital signal examples. The <a href="./rf-constructors.html">RF Constructors</a> page introduces the component families; <a href="./circuit-examples.html">Circuit examples</a> shows complete RF networks. Physical-model design notes and equation provenance are maintained in the repository&#39;s <a href="https://github.com/JerryWiltz/nP/tree/master/developmentDocs" target="_blank" rel="noreferrer"><code>developmentDocs/</code></a> directory.</p><p>For noise figure and output noise density, see <a href="./noise.html">Noise</a>. For IP2, IP3, and harmonics, see <a href="./intermodulation.html">Intermodulation</a>.</p>',22)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
